    intro: "शाळाघर शाळेची हजेरी, गुण, असाइनमेंट आणि संदेशांची नोंद ठेवते, आणि ती फक्त शाळा परवानगी देते त्या लोकांनाच दाखवते: शाळेचा कर्मचारीवर्ग, प्रत्येक मुलाचे पालक आणि स्वतः मूल. काय ठेवले जाते, कोण पाहू शकते, ते कुठे जाते आणि तुम्ही काय मागू शकता, हे या पानावर लिहिले आहे. हे पालकांसाठी लिहिले आहे; जे इथे नाही ते शाळेचे कार्यालय सांगू शकते.",
    s1Title: "डेटाची जबाबदारी शाळेची आहे",
    s1a: "विद्यार्थ्याची प्रत्येक नोंद एकाच शाळेची असते. शाळा खाते तयार करते, किंवा ज्याने खाते तयार होते तो कोड देते, आणि तिचा कोणता कर्मचारी काय पाहू शकतो हे ठरवते. भारताच्या डिजिटल वैयक्तिक डेटा संरक्षण कायदा 2023 नुसार शाळा डेटा फिड्युशियरी आहे, आणि 18 वर्षांखालील प्रत्येक व्यक्ती मूल आहे.",
    s1b: "शाळाघराचा सर्व्हर जो कोणी चालवतो, तो शाळेसाठी प्रोसेसर म्हणून काम करतो. ऑपरेटरला शाळांची आणि आमंत्रणांची यादी दिसते, आणि शाळेच्या आत काहीही नाही: हजेरी नाही, गुण नाहीत, संदेश नाहीत. शाळेच्या आत कोणतीही डोकावणी वेळमर्यादित असते, कारणासह नोंदवली जाते, आणि त्या शाळेला तिच्या सुरक्षा केंद्रात दिसते.",
